import{_ as a,c as d,o as e,b0 as n}from"./chunks/framework.C5ev1SXp.js";const s="/scm-docs/assets/ping-journey.C6R2nVV2.svg",u=JSON.parse('{"title":"LV050-一次ping的完整旅程","description":null,"frontmatter":{"title":"LV050-一次ping的完整旅程","date":"2026-10-14T21:56:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:56:00.895Z","fulluuid":"b528c36d500f4042bce390272674c6d8","useduuid":"b528c36d5"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV050-一次ping的完整旅程.md","lastUpdated":1792231946000}'),r={name:"sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.md"};function o(c,t,l,i,p,h){return e(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="lv050-一次ping的完整旅程" tabindex="-1">LV050-一次ping的完整旅程 <a class="header-anchor" href="#lv050-一次ping的完整旅程" aria-label="Permalink to &quot;LV050-一次ping的完整旅程&quot;">​</a></h1><h2 id="一、-为什么要按时间顺序串一遍" tabindex="-1">一、 为什么要按时间顺序串一遍 <a class="header-anchor" href="#一、-为什么要按时间顺序串一遍" aria-label="Permalink to &quot;一、 为什么要按时间顺序串一遍&quot;">​</a></h2><p>前面几篇是分段讲的：分层（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0077c57a0b5fb.html">LV001</a>）、封装与帧（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb00a1f4c6d9e02.html">LV005</a>）、地址与掩码（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0119ba6c38b7d.html">LV010</a>）、网关与跨网段（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.html">LV015</a>）、设备与转发（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0169159fefb70.html">LV020</a>）、ARP（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030</a>）、传输层（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.html">LV035</a>）、DHCP（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0326cce94ffc3.html">LV040</a>）、调试工具（<a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0347a8c2e0d9b.html">LV045</a>）。</p><p>但真实的通信是<strong>一次把好几层都用上</strong>，只学分段容易出现&quot;每篇都懂、合起来说不清&quot;的情况。</p><p>这一篇按<strong>时间顺序</strong>把一次 ping 的报文走一遍。设定很具体：</p><table tabindex="0"><thead><tr><th>角色</th><th>地址</th><th>配置</th></tr></thead><tbody><tr><td>板子</td><td><code>192.168.16.30/24</code></td><td>静态，网关 <code>192.168.16.1</code></td></tr><tr><td>PC</td><td><code>192.168.16.100/24</code></td><td>手工填，同网段</td></tr><tr><td>连接方式</td><td>网线直连（或经同一台交换机）</td><td>—</td></tr></tbody></table><img src="'+s+`" alt="一次 ping 在不同接法下的报文走向"><h2 id="二、-场景一-直连同网段的完整流水账" tabindex="-1">二、 场景一：直连同网段的完整流水账 <a class="header-anchor" href="#二、-场景一-直连同网段的完整流水账" aria-label="Permalink to &quot;二、 场景一：直连同网段的完整流水账&quot;">​</a></h2><h3 id="_1-逐步流水账" tabindex="-1">1. 逐步流水账 <a class="header-anchor" href="#_1-逐步流水账" aria-label="Permalink to &quot;1. 逐步流水账&quot;">​</a></h3><p>在 PC 上敲下 <code>ping 192.168.16.30</code>，接下来发生的事按顺序是：</p><table tabindex="0"><thead><tr><th>#</th><th>谁做</th><th>做什么</th><th>依据什么判断</th><th>对应代码/文件</th></tr></thead><tbody><tr><td>1</td><td>PC</td><td>判断目的 IP 与自己是否同网段</td><td><code>192.168.16.30 &amp; 255.255.255.0 == 本机网络地址</code> → 同网段，<strong>不走网关</strong></td><td>—</td></tr><tr><td>2</td><td>PC</td><td>查 ARP 缓存里有没有 <code>192.168.16.30</code> 的 MAC</td><td>没有 → 发起 ARP</td><td>—</td></tr><tr><td>3</td><td>PC</td><td><strong>广播</strong> ARP 请求：&quot;谁是 192.168.16.30&quot;</td><td>目的 MAC = <code>FF:FF:FF:FF:FF:FF</code></td><td>—</td></tr><tr><td>4</td><td>板子 DM9000</td><td>收到帧，触发中断（PG6 下降沿）</td><td>网卡按目的 MAC 过滤后收下</td><td><code>dm9000.c</code></td></tr><tr><td>5</td><td>板子主循环</td><td>取包 → 送进协议栈</td><td>每 1 ms 由 <code>lwip_comm_poll()</code> 调用</td><td><code>ethernetif.c</code>、<code>lwip_comm.c</code></td></tr><tr><td>6</td><td>板子 lwIP</td><td>看以太网帧类型 <code>0x0806</code> → 交给 ARP</td><td>类型字段分流</td><td><code>ethernet.c</code>、<code>etharp.c</code></td></tr><tr><td>7</td><td>板子 lwIP</td><td>记录 PC 的映射，<strong>单播</strong>回 ARP 应答</td><td>请求里带了 PC 的 MAC，不必广播</td><td><code>etharp.c</code></td></tr><tr><td>8</td><td>PC</td><td>收到应答，写入 ARP 缓存</td><td>之后一段时间不用再问</td><td>—</td></tr><tr><td>9</td><td>PC</td><td>构造 ICMP Echo 请求 → 加 IP 头 → 加以太网头（目的 MAC = 板子）</td><td>目的 IP = <code>192.168.16.30</code>、协议号 1</td><td>—</td></tr><tr><td>10</td><td>板子</td><td>收到帧，类型 <code>0x0800</code> → 交给 IP</td><td>—</td><td><code>ip4.c</code></td></tr><tr><td>11</td><td>板子</td><td>IP 头目的地址是自己 → 协议号 1 → 交给 ICMP</td><td>—</td><td><code>icmp.c</code></td></tr><tr><td>12</td><td>板子</td><td>生成 Echo 应答，<strong>交换源/目的地址</strong>回发</td><td>—</td><td><code>icmp.c</code></td></tr><tr><td>13</td><td>PC</td><td>收到应答，<code>ping</code> 打印一行 <code>时间=... TTL=...</code></td><td>—</td><td>—</td></tr></tbody></table><h3 id="_2-整个过程里最关键的两步" tabindex="-1">2. 整个过程里最关键的两步 <a class="header-anchor" href="#_2-整个过程里最关键的两步" aria-label="Permalink to &quot;2. 整个过程里最关键的两步&quot;">​</a></h3><p>（1）<strong>第 1 步</strong>决定了&quot;要不要找网关&quot;——同网段就不找。这也是为什么直连实验里网关填错也不影响。</p><p>（2）<strong>第 7 步的单播</strong>决定了后续通信的量级——ARP 只广播一次，之后全靠缓存。如果没有缓存，每个 ICMP 包都会带来一次广播风暴。</p><h3 id="_3-第一包为什么慢" tabindex="-1">3. 第一包为什么慢 <a class="header-anchor" href="#_3-第一包为什么慢" aria-label="Permalink to &quot;3. 第一包为什么慢&quot;">​</a></h3><p>再补一个观察：<code>ping</code> 的第一包通常比后续几包<strong>慢</strong>（经常是几毫秒 vs 零点几毫秒），因为第一包里含了 ARP 的一问一答。</p><p>这个现象可以直接反过来用作排错依据：<strong>如果连第一包都不通，问题多半在 ARP 或更下面，而不是 IP 以上。</strong></p><h2 id="三、-场景二-中间多了一台交换机" tabindex="-1">三、 场景二：中间多了一台交换机 <a class="header-anchor" href="#三、-场景二-中间多了一台交换机" aria-label="Permalink to &quot;三、 场景二：中间多了一台交换机&quot;">​</a></h2><h3 id="_1-流水账一行都不用改" tabindex="-1">1. 流水账一行都不用改 <a class="header-anchor" href="#_1-流水账一行都不用改" aria-label="Permalink to &quot;1. 流水账一行都不用改&quot;">​</a></h3><p>把网线从&quot;直连&quot;改成&quot;各自接到同一台交换机&quot;，上面的流水账<strong>一行都不用改</strong>：</p><table tabindex="0"><thead><tr><th>差异</th><th>说明</th></tr></thead><tbody><tr><td>板子的 ARP 请求先进交换机</td><td>交换机看目的 MAC 是广播 → 向其它口泛洪</td></tr><tr><td>交换机学到了 PC 与板子的 MAC</td><td>后续帧就能精准转发，不再泛洪</td></tr><tr><td>板子与 PC 的配置</td><td><strong>完全不变</strong>（仍必须同网段）</td></tr></tbody></table><h3 id="_2-新增的失败点" tabindex="-1">2. 新增的失败点 <a class="header-anchor" href="#_2-新增的失败点" aria-label="Permalink to &quot;2. 新增的失败点&quot;">​</a></h3><p>从&quot;能否 ping 通&quot;的角度看，直连与同交换机是等价的。新增的失败点只有交换机本身：</p><ul><li>是否通电、指示灯是否正常；</li><li>端口是否协商成功（百兆/千兆、双工是否匹配）；</li><li>有没有把两个口接成环（会引发广播风暴，现象是网络时通时断）。</li></ul><h2 id="四、-场景三-跨网段通信" tabindex="-1">四、 场景三：跨网段通信 <a class="header-anchor" href="#四、-场景三-跨网段通信" aria-label="Permalink to &quot;四、 场景三：跨网段通信&quot;">​</a></h2><h3 id="_1-流水账在前两步就分岔" tabindex="-1">1. 流水账在前两步就分岔 <a class="header-anchor" href="#_1-流水账在前两步就分岔" aria-label="Permalink to &quot;1. 流水账在前两步就分岔&quot;">​</a></h3><p>现在把板子放在 A 网段、PC 放在 B 网段（中间是路由器）：</p><table tabindex="0"><thead><tr><th>角色</th><th>地址</th></tr></thead><tbody><tr><td>板子</td><td><code>192.168.16.30/24</code>，网关 <code>192.168.16.1</code></td></tr><tr><td>PC</td><td><code>192.168.1.100/24</code>，网关 <code>192.168.1.1</code></td></tr><tr><td>路由器</td><td>接口 A = <code>192.168.16.1</code>，接口 B = <code>192.168.1.1</code></td></tr></tbody></table><p>这次的流水账：</p><table tabindex="0"><thead><tr><th>#</th><th>谁做</th><th>关键动作</th></tr></thead><tbody><tr><td>1</td><td>PC</td><td>判断不同网段 → <strong>交给默认网关</strong>，而不是直接 ARP 板子</td></tr><tr><td>2</td><td>PC</td><td>ARP 的是<strong>网关的 MAC</strong>，不是板子的</td></tr><tr><td>3</td><td>PC</td><td>以太网帧：目的 MAC = 网关，但 <strong>IP 头里目的地址仍是 <code>192.168.16.30</code></strong></td></tr><tr><td>4</td><td>路由器</td><td>收到帧 → 查路由表 → 从接口 A 转发出去，并<strong>重写链路层帧头</strong>（源 MAC 换成自己，TTL 减 1）</td></tr><tr><td>5</td><td>板子</td><td>收到请求，生成应答；目的 IP 是 <code>192.168.1.100</code> → <strong>不同网段 → 交给自己的网关</strong></td></tr><tr><td>6</td><td>路由器</td><td>反向转发回 PC</td></tr></tbody></table><h3 id="_2-必须记住的结论" tabindex="-1">2. 必须记住的结论 <a class="header-anchor" href="#_2-必须记住的结论" aria-label="Permalink to &quot;2. 必须记住的结论&quot;">​</a></h3><blockquote><p><strong>IP 头全程不变，以太网头逐跳重写。</strong></p></blockquote><p>这就是&quot;MAC 只在一条链路内有效&quot;的具体含义。也正因为如此，<strong>跨网段通信要求双方都能找到网关</strong>：</p><p>如果板子没配网关（或配了不存在的），它能收到请求（因为请求是路由器送上门的），却<strong>发不出去应答</strong>——现象就是&quot;PC 一直超时，但板子日志显示确实收到了包&quot;。这个现象很有辨识度，遇到它直接去查网关，不要怀疑收包路径。</p><p>本实验只有直连或同交换机两种接法，所以正确做法就是<strong>双方配成同网段</strong>，而不是去折腾网关。网关本身的机制见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.html">LV015-网关与跨网段通信</a>。</p><h2 id="五、-场景四-从局域网到公网" tabindex="-1">五、 场景四：从局域网到公网 <a class="header-anchor" href="#五、-场景四-从局域网到公网" aria-label="Permalink to &quot;五、 场景四：从局域网到公网&quot;">​</a></h2><p>如果要访问 <code>www.example.com</code> 这种外网地址，还要多两件事：</p><table tabindex="0"><thead><tr><th>环节</th><th>做什么</th></tr></thead><tbody><tr><td>DNS</td><td>把域名解析成 IP（否则只能直接敲 IP）</td></tr><tr><td>NAT</td><td>家用路由器把私有地址 <code>192.168.16.30</code> 换成自己的公网地址，并记住&quot;这个连接是谁的&quot;，回包再换回来</td></tr></tbody></table><p>这也解释了为什么私有地址能重复使用：<strong>它只在内网可见，出门就被 NAT 换掉了</strong>。</p><p>反过来说清本工程的定位：Bootloader 只实现了 IP / ICMP / TCP / UDP / ARP 这一小块，<strong>既没有 DHCP 也没有 DNS</strong>，也没有公网地址。它的目标始终是&quot;在同一局域网内被 PC 找到并升级&quot;，不是上网。</p><h2 id="六、-把流水账落回实测输出与排错链" tabindex="-1">六、 把流水账落回实测输出与排错链 <a class="header-anchor" href="#六、-把流水账落回实测输出与排错链" aria-label="Permalink to &quot;六、 把流水账落回实测输出与排错链&quot;">​</a></h2><h3 id="_1-串口实测输出" tabindex="-1">1. 串口实测输出 <a class="header-anchor" href="#_1-串口实测输出" aria-label="Permalink to &quot;1. 串口实测输出&quot;">​</a></h3><p>板子启动后串口会打印（详见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a> 第一节）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DM9000: ID = 0x90000A46                          ← 网卡认到了，链路层 OK</span></span>
<span class="line"><span>lwIP: MAC 02-00-00-XX-XX-XX, IP 192.168.16.30    ← 网络层参数就绪</span></span>
<span class="line"><span>lwIP: RX mode = interrupt (EXTI6 falling edge)   ← 收包路径就绪</span></span>
<span class="line"><span>lwIP: ready, ping 192.168.16.30 to test          ← 可以开始场景一了</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>会读这四行，就等于有了四个观测点：任何一行不对，排查范围立刻缩小一个层级。</p><h3 id="_2-一张排错决策树" tabindex="-1">2. 一张排错决策树 <a class="header-anchor" href="#_2-一张排错决策树" aria-label="Permalink to &quot;2. 一张排错决策树&quot;">​</a></h3><p>把前面几篇合起来，得到一条<strong>从下往上</strong>的排查链（顺序不能反）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>网口灯亮吗？ ── 不亮 ──▶ 网线 / 对端 / PHY 上电</span></span>
<span class="line"><span>  │亮</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>串口有 DM9000: ID = 0x90000A46 吗？ ── 没有 ──▶ FSMC 初始化 / 片选 / 总线时序</span></span>
<span class="line"><span>  │有</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>PC 拿到的是 169.254.x.x 吗？ ── 是 ──▶ 地址没配好，手工填同网段 IP</span></span>
<span class="line"><span>  │不是</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>两边同网段吗？（IP &amp; 掩码 比对） ── 不同 ──▶ 改成同网段</span></span>
<span class="line"><span>  │同</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>PC 上 arp -a 能看到板子的 IP 吗？ ── 看不到 ──▶ ARP 没通：收包模式 / 中断标志 / 交换机</span></span>
<span class="line"><span>  │看到</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>还是 ping 不通 ──▶ 才轮到查协议栈上层（ICMP、收发缓冲、计数统计）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p><strong>这条链的价值在于：绝大多数&quot;ping 不通&quot;都发生在最上面三层</strong>，而不是 lwIP。</p><h3 id="_3-两个与-lwip-相关的现象" tabindex="-1">3. 两个与 lwIP 相关的现象 <a class="header-anchor" href="#_3-两个与-lwip-相关的现象" aria-label="Permalink to &quot;3. 两个与 lwIP 相关的现象&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>原理</th></tr></thead><tbody><tr><td>第一次 ping 慢、后续快</td><td>第一包含 ARP 一问一答</td></tr><tr><td>ping 通但 TCP 连不上</td><td>说明 IP / ICMP / ARP 都好，问题在传输层——多半是端口被占或单连接策略（见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">网络通信实验</a> 第三节）</td></tr></tbody></table><h2 id="七、-小结与参考资料" tabindex="-1">七、 小结与参考资料 <a class="header-anchor" href="#七、-小结与参考资料" aria-label="Permalink to &quot;七、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>一次 ping 会把<strong>分层、封装、IP 与掩码、设备转发、ARP</strong> 全部用上，是检验网络配置最省事的工具。</li><li>同网段：不走网关，直接 ARP 目的 IP；跨网段：交给网关，ARP 的是网关。</li><li><strong>IP 头全程不变，以太网头逐跳重写。</strong></li><li>直连与同交换机在&quot;能否 ping 通&quot;上等价，配置要求也相同：双方同网段。</li><li>上网还要 DNS 与 NAT；本工程的目标不是上网，而是在局域网内被找到。</li><li>排查顺序永远<strong>从物理层往上</strong>：先灯、再网卡 ID、再地址、再 ARP，最后才是协议栈。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>实验步骤与实测输出：<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a></li><li>网卡驱动：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ethernet/dm9000.c" target="_blank" rel="noreferrer"><code>dm9000.c</code></a></li><li>协议栈初始化与轮询：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/lwip_comm.c" target="_blank" rel="noreferrer"><code>lwip_comm.c</code></a></li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第 1.6 节</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,58)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
